import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.Dsf4_p3t.js";const g=JSON.parse('{"title":"平台原生调优层","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/native-tuning.md","filePath":"zh/guide/native-tuning.md","lastUpdated":1791194813000}'),a={name:"zh/guide/native-tuning.md"};function i(n,e,s,r,l,h){return d(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="平台原生调优层" tabindex="-1">平台原生调优层 <a class="header-anchor" href="#平台原生调优层" aria-label="Permalink to &quot;平台原生调优层&quot;">​</a></h1><p>平台原生调优层位于 <code>neoflux/src/native/</code>（命名空间 <code>neoflux::native</code>），是 框架中<strong>唯一</strong>允许直接调用操作系统底层 API 的地方——线程调度、定时器精度、 CPU 特性与缓存拓扑探测。这里的一切都是 <strong>best-effort</strong>：在受限系统上（权限 不足、内核特殊、CPU 不支持）静默降级为安全的 no-op 并记录一条日志，绝不抛异常、 绝不使调用方失败。</p><p>多数情况下你不需要直接调用它——渲染线程与事件循环已经替你接好了。本页说明每个 入口在各平台的行为、自动接入点，以及何时值得手动调用。</p><h2 id="入口一览" tabindex="-1">入口一览 <a class="header-anchor" href="#入口一览" aria-label="Permalink to &quot;入口一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>开销</th><th>何时调用</th></tr></thead><tbody><tr><td><code>TuneRenderThread()</code></td><td>渲染线程的调度整形（提升优先级 / 向平台多媒体调度器注册）。</td><td>一次性，极低</td><td><code>RenderLoop</code> 顶部、首个 GPU 工作之前自动调用。</td></tr><tr><td><code>TuneUiThread()</code></td><td>UI/事件循环线程的调度整形（定时器精度 + 优先级）。</td><td>一次性，极低</td><td><code>EventLoop::Run()</code> 开头自动调用。</td></tr><tr><td><code>PinThreadToBigCores()</code></td><td>在 big.LITTLE / 混合架构上把当前线程绑定到大核/性能核。</td><td>一次性</td><td><code>TuneRenderThread()</code> 之后自动调用。若你自建对 P 核敏感的工作线程则手动调用。</td></tr><tr><td><code>DetectCpuFeatures()</code></td><td>SIMD 能力快照（<code>sse42</code>、<code>avx2</code>、<code>neon</code>、<code>neon_fp16</code>）。</td><td>极低，可重复</td><td>任意位置；结果仅供参考，调用方必须保留标量回退路径。</td></tr><tr><td><code>DetectCacheTopology()</code></td><td>运行时缓存几何（<code>CacheInfo</code>：一致性行大小 + L1d/L2/L3 字节数）。</td><td>低（一次性探测）</td><td>启动时一次，或在为自建数据结构定尺寸之前。</td></tr><tr><td><code>PrefetchForRead(const void*)</code></td><td>单行读预取提示。</td><td>免费（单条指令）</td><td>你自有的紧凑循环里，提前一次迭代。</td></tr><tr><td><code>PrefetchForWrite(const void*)</code></td><td>单行写预取提示（独占 / 为写准备）。</td><td>免费</td><td>向新领取的槽位或 slab 写入之前。</td></tr><tr><td><code>VerifyCacheLineConfig()</code></td><td>对比运行时行大小与编译期 <code>config::kCacheLineSize</code>；若硬件行更宽则<strong>只告警一次</strong>。</td><td>低</td><td>启动时一次（调试/遥测），在日志初始化之后。</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">所有入口均为 <code>noexcept</code></p><p>它们不会抛异常、不会中止进程。OS 调用失败只会变成一条日志并返回默认值——调用点 永远不会成为故障源。</p></div><h2 id="运行时配置-gflags" tabindex="-1">运行时配置（gflags） <a class="header-anchor" href="#运行时配置-gflags" aria-label="Permalink to &quot;运行时配置（gflags）&quot;">​</a></h2><p>所有调优尝试都可在运行时配置；flag 定义在 <code>neoflux/src/core/flags.cpp</code>， 文档见两份 README：</p><table tabindex="0"><thead><tr><th>Flag</th><th>默认值</th><th>作用</th></tr></thead><tbody><tr><td><code>--native_tuning</code></td><td><code>true</code></td><td>总开关：<code>false</code> 时以下所有入口均变为 no-op。</td></tr><tr><td><code>--native_render_rt_priority</code></td><td><code>1</code></td><td>Linux/Android 渲染线程 SCHED_FIFO 优先级（1..99）。</td></tr><tr><td><code>--native_thread_nice</code></td><td><code>-5</code></td><td>Linux/Android 渲染线程（降级路径）与 UI 线程的 nice 值。</td></tr><tr><td><code>--native_bigcore_threshold_permille</code></td><td><code>950</code></td><td>大核判定阈值（相对最快核频率的千分比，500..1000）。</td></tr><tr><td><code>--native_mmcss_profile</code></td><td><code>Games</code></td><td>Windows MMCSS profile 名称。</td></tr><tr><td><code>--native_timer_period_ms</code></td><td><code>1</code></td><td>Windows <code>timeBeginPeriod</code> 定时器精度（毫秒，<code>0</code> = 关闭）。</td></tr></tbody></table><p>越界值会被钳制；OS 拒绝时一切尝试依旧静默降级——flag 只改变&quot;多激进&quot;， 绝不改变正确性。</p><h2 id="平台行为矩阵" tabindex="-1">平台行为矩阵 <a class="header-anchor" href="#平台行为矩阵" aria-label="Permalink to &quot;平台行为矩阵&quot;">​</a></h2><p><code>✓</code> = 已实现；<code>no-op</code> = 在该平台上刻意不做任何事。</p><table tabindex="0"><thead><tr><th>能力</th><th>Windows</th><th>Linux</th><th>Android</th><th>macOS</th><th>iOS</th></tr></thead><tbody><tr><td><code>TuneRenderThread</code></td><td>MMCSS &quot;Games&quot; 配置，否则 <code>ABOVE_NORMAL</code></td><td><code>SCHED_FIFO</code> 优先级 1，否则 nice −5</td><td><code>SCHED_FIFO</code>→nice，否则 no-op</td><td>QoS <code>USER_INTERACTIVE</code></td><td>QoS <code>USER_INTERACTIVE</code></td></tr><tr><td><code>TuneUiThread</code></td><td>1 ms 定时器精度 + <code>ABOVE_NORMAL</code> 进程类别</td><td>nice −5</td><td>nice −5（通常被拒)</td><td>no-op（已是 <code>USER_INTERACTIVE</code>）</td><td>no-op</td></tr><tr><td><code>PinThreadToBigCores</code></td><td>通过逻辑处理器拓扑的 <code>EfficiencyClass</code></td><td>对 ≥95% 最高频率的核调 <code>sched_setaffinity</code></td><td>同 Linux</td><td>no-op（由 QoS 决定集群）</td><td>no-op</td></tr><tr><td><code>DetectCpuFeatures</code></td><td>cpuid / xgetbv</td><td>cpuid / <code>getauxval</code></td><td><code>getauxval</code></td><td><code>sysctl</code>（Intel）/ ABI（Silicon）</td><td>ABI（Silicon）</td></tr><tr><td><code>DetectCacheTopology</code></td><td>cpuid leaf 1 + leaf 4</td><td>sysfs 缓存树</td><td>sysfs 缓存树</td><td><code>sysctl hw.*</code></td><td><code>sysctl hw.*</code></td></tr><tr><td><code>PrefetchForRead/Write</code></td><td><code>_mm_prefetch</code></td><td><code>__builtin_prefetch</code></td><td><code>__builtin_prefetch</code></td><td><code>__builtin_prefetch</code></td><td><code>__builtin_prefetch</code></td></tr><tr><td><code>VerifyCacheLineConfig</code></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr></tbody></table><p>全部基于 intrinsic 实现：本层任何地方都不使用手写内联汇编（cpuid 用 <code>__cpuid</code>/<code>__cpuidex</code>，预取用 <code>__builtin_prefetch</code> / <code>_mm_prefetch</code>）。</p><p>这句话只针对<strong>本层</strong>。框架确实带有少量手写 SIMD 内核——它们在下一级目录 <code>src/native/asm/</code> 里，通过 C ABI 接入，而不是从这里调用。参见 <a href="./native-asm">手写汇编内核</a>。</p><h2 id="自动接入点" tabindex="-1">自动接入点 <a class="header-anchor" href="#自动接入点" aria-label="Permalink to &quot;自动接入点&quot;">​</a></h2><p>正常路径下调优是免费获得的：</p><ul><li><strong><code>RenderLoop</code></strong> —— 线程启动时调用一次 <code>TuneRenderThread()</code>，随后调用 <code>PinThreadToBigCores()</code>，再进入帧循环。这个线程的调度延迟会直接转化为帧节拍 抖动。</li><li><strong><code>EventLoop::Run()</code></strong> —— 开头调用一次 <code>TuneUiThread()</code>。在 Windows 上正是它 把默认约 15.6 ms 的定时器粒度变为 1 ms；否则 60 FPS 的 <code>condition_variable::wait_for()</code> 会出现肉眼可见的抖动。</li><li><strong>启动 / 遥测</strong> —— <code>DetectCpuFeatures()</code>、<code>DetectCacheTopology()</code> 与 <code>VerifyCacheLineConfig()</code> 开销都很低，在 <code>google::InitGoogleLogging()</code> 之后 调用一次即可。框架会以 <code>INFO</code> 记录检测到的拓扑，必要时抛出缓存行告警（见下）。</li></ul><h3 id="何时需要手动调用" tabindex="-1">何时需要手动调用 <a class="header-anchor" href="#何时需要手动调用" aria-label="Permalink to &quot;何时需要手动调用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>调用</th></tr></thead><tbody><tr><td>你新建了一个做 GPU 相邻或延迟敏感工作的线程。</td><td><code>TuneRenderThread()</code>（+ <code>PinThreadToBigCores()</code>）。</td></tr><tr><td>想在 bug 报告里带一份缓存几何的 info 级转储。</td><td><code>DetectCacheTopology()</code> + <code>VerifyCacheLineConfig()</code>。</td></tr><tr><td>你自有无锁 / 缓存敏感的数据结构，想按真实行大小定填充。</td><td><code>DetectCacheTopology().line_size</code>。</td></tr><tr><td>你在自控的热循环里流式遍历一块缓冲区。</td><td>提前一次迭代调 <code>PrefetchForRead()</code> / <code>PrefetchForWrite()</code>。</td></tr><tr><td>目标是无桌面或非桌面平台，想确认实际生效了什么。</td><td>读 <code>native:</code> 开头的日志行——每条路径都会记录一次结果。</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">不要逐帧调用调优函数</p><p>它们用于一次性的线程/进程整形。在循环里反复调 <code>PinThreadToBigCores()</code> 会与调度器 对抗，可能<strong>降低</strong>吞吐。在线程启动时调一次即可。</p></div><h2 id="缓存行定尺寸与编译期配置" tabindex="-1">缓存行定尺寸与编译期配置 <a class="header-anchor" href="#缓存行定尺寸与编译期配置" aria-label="Permalink to &quot;缓存行定尺寸与编译期配置&quot;">​</a></h2><p><code>config::kCacheLineSize</code>（见 <code>neoflux/include/neoflux/core/config.h</code>）是用于把 SPSC 环形队列头/尾填充到不同缓存行的<strong>编译期</strong>对齐值。默认 64，可在配置期覆盖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_CACHE_LINE_SIZE=128</span></span></code></pre></div><p>运行时的 <code>DetectCacheTopology()</code> / <code>VerifyCacheLineConfig()</code> 这一对，正是为了 捕捉编译期取值比硬件行<strong>更窄</strong>的情况。关键例子是 <strong>Apple M 系列</strong>：其 L1 数据 缓存一致性行为 <strong>128 字节</strong>；按 64 字节填充的队列可能让相邻两个对象落在同一行上， 于是生产者与消费者仍会在核间来回弹跳该行——伪共享并未因填充而消除。任何 Apple Silicon 目标请这样构建：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_CACHE_LINE_SIZE=128</span></span></code></pre></div><p><code>VerifyCacheLineConfig()</code> 比较 <code>CacheInfo::line_size</code> 与 <code>config::kCacheLineSize</code>，并且<strong>至多记录一次</strong>：</p><table tabindex="0"><thead><tr><th>运行时 vs 编译期</th><th>日志</th></tr></thead><tbody><tr><td>运行时 <strong>&gt;</strong> 编译期</td><td><code>WARNING</code> —— 对齐不足、存在伪共享风险，并给出确切的 <code>-DNEOFLUX_CACHE_LINE_SIZE=</code> 修复方式。</td></tr><tr><td>运行时 <strong>==</strong> 编译期</td><td><code>INFO</code> —— 匹配。</td></tr><tr><td>运行时 <strong>&lt;</strong> 编译期</td><td><code>INFO</code> —— 更保守（安全，代价是些许内存）。</td></tr><tr><td>探测不可用（无 sysfs、未知 CPU）</td><td><code>INFO</code> —— 缓存行按 64 B 假定；不做比较。</td></tr></tbody></table><p>完整的常量参考见 <a href="./configuration">配置</a>。</p><h2 id="验证实际发生了什么" tabindex="-1">验证实际发生了什么 <a class="header-anchor" href="#验证实际发生了什么" aria-label="Permalink to &quot;验证实际发生了什么&quot;">​</a></h2><p>每条路径恰好记录一次，前缀为 <code>native:</code>。一次健康的桌面运行大致如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I native: cache topology detected -- line=64B L1d=49152B L2=1310720B L3=56623104B</span></span>
<span class="line"><span>I native: compile-time cache line matches runtime (64B)</span></span>
<span class="line"><span>I native: render thread -&gt; SCHED_FIFO prio=1</span></span>
<span class="line"><span>I native: ui thread -&gt; nice -5</span></span></code></pre></div><p>在 128 字节缓存行的机器上用 64 字节构建时，则会看到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>W native: runtime cache line (128B) exceeds compile-time</span></span>
<span class="line"><span>  config::kCacheLineSize (64B); SPSC queue head/tail may still share a</span></span>
<span class="line"><span>  coherence line -&gt; false sharing. Rebuild with</span></span>
<span class="line"><span>  -DNEOFLUX_CACHE_LINE_SIZE=128 to fix it.</span></span></code></pre></div><p>某条 <code>native:</code> 日志缺失绝不是错误——它意味着该平台路径是刻意的 no-op（例如 Apple 上的大核绑定，那里 QoS 已经驱动集群放置）。</p><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./configuration">配置</a> —— <code>config::kCacheLineSize</code> 及其他编译时常量。</li><li><a href="./debugging">调试与调优</a> —— 日志参数与渲染队列背压问题。</li><li><a href="./cross-platform">跨平台</a> —— 各平台翻译单元如何在配置期被选择。</li><li><a href="./native-asm">手写汇编内核</a> —— <code>src/native/asm/</code> 下的汇编 SIMD 内核， 以及它们为什么不用 intrinsic 写。</li></ul><hr><p><em>自 NeoFlux 0.3.1-alpha + neoflux-fix 补丁集起提供。</em></p>`,39)])])}const u=t(a,[["render",i]]);export{g as __pageData,u as default};
